"""A2A push notifications: callback URL policy, config store, and HTTP transport.

The orchestrator supplies ``pushNotificationConfig.url`` inline on
``message/send`` / ``message/stream`` or via ``tasks/pushNotificationConfig/set``.
Rasa stores it in-memory per ``task_id`` and POSTs task updates to each
registered URL. Callback URLs are client-controlled, so registration and
send paths enforce :class:`PushNotificationUrlPolicy` SSRF safeguards,
including DNS resolution to block hostnames that resolve to private or
loopback addresses. HTTP POSTs use ``follow_redirects=False`` so a
registered public callback cannot redirect into a blocked target.

**Residual risk (DNS rebinding):** ``validate_url`` resolves hostnames via
``socket.getaddrinfo``, but ``httpx`` performs a separate lookup when opening
the TCP connection. Validation and connect are therefore not atomic; an
orchestrator-controlled hostname with attacker-controlled DNS could pass
policy checks yet rebind to a different address at POST time. Dual validation
(at registration and send) does not close this TOCTOU gap. Operators should
keep push notifications disabled unless required, set
``push_notification_allowed_hosts``, prefer HTTPS callbacks (TLS certificate
verification limits rebinding to internal/metadata targets), and treat
callback registration as a trusted orchestrator action. A future hardening
path is single-resolve IP-pinned POST (connect to the validated IP with the
original hostname in the ``Host`` header and TLS SNI).
"""

from __future__ import annotations

import asyncio
import ipaddress
import socket
from typing import TYPE_CHECKING
from urllib.parse import urlparse

import httpx
from a2a.server.tasks import (
    BasePushNotificationSender,
    InMemoryPushNotificationConfigStore,
    PushNotificationConfigStore,
    PushNotificationSender,
)
from a2a.types import PushNotificationConfig, Task

from rasa.core.a2a_server.errors import A2APushNotificationUrlRejected
from rasa.utils.url_tools import UrlSchema, get_url_schema

if TYPE_CHECKING:
    from rasa.core.a2a_server.config import A2AServerConfig

_ALLOWED_SCHEMES = frozenset({UrlSchema.HTTP, UrlSchema.HTTPS})
_LOCALHOST_NAMES = frozenset({"localhost", "localhost.localdomain"})
_BLOCKED_NETWORK_TARGET_MESSAGE = (
    "Push notification callback URLs must not target loopback, "
    "link-local, or private network addresses."
)
_UNRESOLVABLE_HOSTNAME_MESSAGE = (
    "Push notification callback hostname could not be resolved."
)
_DNS_RESOLVE_TIMEOUT_SECONDS = 5.0
_DNS_RESOLVE_TIMEOUT_MESSAGE = (
    "Push notification callback hostname resolution timed out."
)
# Bounded connect (DNS + TCP) and overall POST time for orchestrator callbacks.
_PUSH_NOTIFICATION_HTTP_TIMEOUT = httpx.Timeout(30.0, connect=5.0)


class PushNotificationUrlPolicy:
    """Validate push callback URLs before registration and before HTTP POST."""

    def __init__(
        self,
        *,
        enabled: bool,
        allowed_hosts: list[str] | None = None,
    ) -> None:
        self._enabled = enabled
        self._allowed_hosts = (
            [host.lower().strip().strip(".") for host in allowed_hosts]
            if allowed_hosts is not None
            else None
        )

    @classmethod
    def from_config(cls, config: A2AServerConfig) -> PushNotificationUrlPolicy:
        """Build a policy from ``A2AServerConfig`` push-notification settings."""
        return cls(
            enabled=config.push_notifications_enabled,
            allowed_hosts=config.push_notification_allowed_hosts,
        )

    @property
    def enabled(self) -> bool:
        return self._enabled

    async def validate_url(self, url: str) -> None:
        """Reject unsafe callback URLs.

        Raises:
            A2APushNotificationUrlRejected: When the URL is not permitted.
        """
        if not self._enabled:
            raise A2APushNotificationUrlRejected(
                "Push notifications are disabled on this server."
            )

        parsed = urlparse(url)
        if get_url_schema(url) not in _ALLOWED_SCHEMES:
            raise A2APushNotificationUrlRejected(
                "Push notification callback URLs must use http or https."
            )
        if not parsed.hostname:
            raise A2APushNotificationUrlRejected(
                "Push notification callback URLs must include a hostname."
            )
        if parsed.username or parsed.password:
            raise A2APushNotificationUrlRejected(
                "Push notification callback URLs must not include credentials."
            )

        hostname = parsed.hostname.lower().rstrip(".")
        if hostname in _LOCALHOST_NAMES or hostname.endswith(".localhost"):
            raise A2APushNotificationUrlRejected(_BLOCKED_NETWORK_TARGET_MESSAGE)
        if self._allowed_hosts is not None and not self._hostname_is_allowlisted(
            hostname
        ):
            raise A2APushNotificationUrlRejected(
                "Push notification callback hostname is not in "
                "push_notification_allowed_hosts."
            )

        try:
            literal_ip = ipaddress.ip_address(hostname)
        except ValueError:
            await self._reject_if_resolved_ips_blocked(hostname)
        else:
            if self._is_blocked_ip(literal_ip):
                raise A2APushNotificationUrlRejected(_BLOCKED_NETWORK_TARGET_MESSAGE)

    async def _reject_if_resolved_ips_blocked(self, hostname: str) -> None:
        """Reject hostnames whose DNS records point at blocked address ranges."""
        for ip in await self._resolve_host_ips(hostname):
            if self._is_blocked_ip(ip):
                raise A2APushNotificationUrlRejected(_BLOCKED_NETWORK_TARGET_MESSAGE)

    @staticmethod
    async def _resolve_host_ips(
        hostname: str,
    ) -> list[ipaddress.IPv4Address | ipaddress.IPv6Address]:
        try:
            addr_infos = await asyncio.wait_for(
                asyncio.to_thread(
                    socket.getaddrinfo,
                    hostname,
                    None,
                    family=socket.AF_UNSPEC,
                    type=socket.SOCK_STREAM,
                ),
                timeout=_DNS_RESOLVE_TIMEOUT_SECONDS,
            )
        except asyncio.TimeoutError as exc:
            # wait_for cancels the await only; the resolver thread may still run
            # until the OS gives up. Use asyncio.TimeoutError (not builtin
            # TimeoutError) for Python 3.10 compatibility.
            raise A2APushNotificationUrlRejected(_DNS_RESOLVE_TIMEOUT_MESSAGE) from exc
        except socket.gaierror as exc:
            raise A2APushNotificationUrlRejected(
                _UNRESOLVABLE_HOSTNAME_MESSAGE
            ) from exc

        resolved: list[ipaddress.IPv4Address | ipaddress.IPv6Address] = []
        seen: set[str] = set()
        for _family, _socktype, _proto, _canonname, sockaddr in addr_infos:
            ip_text = sockaddr[0]
            if ip_text in seen:
                continue
            seen.add(ip_text)
            resolved.append(ipaddress.ip_address(ip_text))

        if not resolved:
            raise A2APushNotificationUrlRejected(_UNRESOLVABLE_HOSTNAME_MESSAGE)
        return resolved

    @staticmethod
    def _is_blocked_ip(ip: ipaddress.IPv4Address | ipaddress.IPv6Address) -> bool:
        # Block anything that is not globally routable (covers private, loopback,
        # link-local, reserved, multicast, unspecified, etc.).
        return not ip.is_global or ip.is_multicast

    def _hostname_is_allowlisted(self, hostname: str) -> bool:
        assert self._allowed_hosts is not None
        for allowed in self._allowed_hosts:
            if hostname == allowed or hostname.endswith(f".{allowed}"):
                return True
        return False


class ValidatingPushNotificationConfigStore(InMemoryPushNotificationConfigStore):
    """In-memory store that enforces callback URL policy before ``set_info``."""

    def __init__(self, policy: PushNotificationUrlPolicy) -> None:
        super().__init__()
        self._policy = policy

    async def set_info(
        self, task_id: str, notification_config: PushNotificationConfig
    ) -> None:
        await self._policy.validate_url(notification_config.url)
        await super().set_info(task_id, notification_config)


class PolicyEnforcingPushNotificationSender(BasePushNotificationSender):
    """HTTP sender that re-validates each callback URL before POST.

    Redirects are disabled on every POST so a policy-approved callback URL
    cannot be used to reach a different, unvalidated target via ``Location``.
    """

    def __init__(
        self,
        httpx_client: httpx.AsyncClient,
        config_store: PushNotificationConfigStore,
        *,
        policy: PushNotificationUrlPolicy,
    ) -> None:
        super().__init__(httpx_client, config_store)
        self._policy = policy

    async def _dispatch_notification(
        self, task: Task, push_info: PushNotificationConfig
    ) -> bool:
        await self._policy.validate_url(push_info.url)
        url = push_info.url
        try:
            headers = None
            if push_info.token:
                headers = {"X-A2A-Notification-Token": push_info.token}
            response = await self._client.post(
                url,
                json=task.model_dump(mode="json", exclude_none=True),
                headers=headers,
                follow_redirects=False,
            )
            response.raise_for_status()
            return True
        except Exception:
            return False


class A2APushNotificationTransport:
    """Bundles push config storage and HTTP POST delivery for A2A tasks.

    Uses the a2a-sdk ``BasePushNotificationSender``, which POSTs the latest
    ``Task`` JSON to each registered ``pushNotificationConfig.url`` whenever
    the ``DefaultRequestHandler`` observes a state transition.
    """

    def __init__(
        self,
        *,
        httpx_client: httpx.AsyncClient | None = None,
        config_store: PushNotificationConfigStore | None = None,
        notifier: PushNotificationSender | None = None,
        url_policy: PushNotificationUrlPolicy | None = None,
    ) -> None:
        self._owns_client = httpx_client is None
        self._httpx_client = httpx_client or httpx.AsyncClient(
            follow_redirects=False,
            timeout=_PUSH_NOTIFICATION_HTTP_TIMEOUT,
        )
        if url_policy is not None:
            self._config_store: PushNotificationConfigStore = (
                ValidatingPushNotificationConfigStore(url_policy)
            )
            self._notifier: PushNotificationSender = (
                PolicyEnforcingPushNotificationSender(
                    self._httpx_client,
                    self._config_store,
                    policy=url_policy,
                )
            )
        else:
            self._config_store = config_store or InMemoryPushNotificationConfigStore()
            self._notifier = notifier or BasePushNotificationSender(
                self._httpx_client,
                self._config_store,
            )

    @property
    def config_store(self) -> PushNotificationConfigStore:
        """Store for per-task ``pushNotificationConfig`` registrations."""
        return self._config_store

    @property
    def notifier(self) -> PushNotificationSender:
        """POSTs task state updates to orchestrator callback URLs."""
        return self._notifier

    async def close(self) -> None:
        """Close the HTTP client when this transport owns it."""
        if self._owns_client:
            await self._httpx_client.aclose()


def create_push_notification_transport(
    config: A2AServerConfig,
) -> A2APushNotificationTransport | None:
    """Build a policy-enforced push transport when enabled in ``endpoints.yml``."""
    if not config.push_notifications_enabled:
        return None
    policy = PushNotificationUrlPolicy.from_config(config)
    return A2APushNotificationTransport(url_policy=policy)
